@replay : ∀ {σ : Type u_2} (j : σ) (d e : σ →₀ ℕ),
  hasseCoeff d (e + Finsupp.single j 1 + d) * (e j + 1) =
    (d j + 1) * hasseCoeff (d + Finsupp.single j 1) (e + Finsupp.single j 1 + d)

@replay : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] {d a : σ →₀ ℕ},
  (∀ j ∈ d.support, a j = 0) →
    ∀ (c : R) (g : MvPolynomial σ R), (hasseDeriv d) ((monomial a) c * g) = (monomial a) c * (hasseDeriv d) g

@Polynomial.hasseDeriv_mul : ∀ {R : Type u_3} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),
  (Polynomial.hasseDeriv k) (f * g) =
    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g

@LinearMap.map_smul : ∀ {R : Type u_3} {M : Type u_4} {M₂ : Type u_5} [inst : Semiring R] [inst_1 : AddCommMonoid M]
  [inst_2 : AddCommMonoid M₂] [inst_3 : Module R M] [inst_4 : Module R M₂] (fₗ : M →ₗ[R] M₂) (c : R) (x : M),
  fₗ (c • x) = c • fₗ x

@hasseDeriv_single_aeval_X : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] (j : σ) (n : ℕ) (f : Polynomial R),
  (hasseDeriv (Finsupp.single j n)) ((Polynomial.aeval (X j)) f) =
    (Polynomial.aeval (X j)) ((Polynomial.hasseDeriv n) f)

@Polynomial.lhom_ext' : ∀ {R : Type u_1} [inst : Semiring R] {M : Type u_2} [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {f g : Polynomial R →ₗ[R] M},
  (∀ (n : ℕ), f ∘ₗ Polynomial.monomial n = g ∘ₗ Polynomial.monomial n) → f = g

@Polynomial.aeval_monomial : ∀ {R : Type u_1} {A : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A]
  [inst_2 : Algebra R A] (x : A) {n : ℕ} {r : R},
  (Polynomial.aeval x) ((Polynomial.monomial n) r) = (algebraMap R A) r * x ^ n

@uniqueAlgEquiv_hasseDeriv : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] [inst_1 : Unique σ] (n : ℕ)
  (P : MvPolynomial σ R),
  (uniqueAlgEquiv R σ) ((hasseDeriv (Finsupp.single default n)) P) = (Polynomial.hasseDeriv n) ((uniqueAlgEquiv R σ) P)

@Polynomial.lhom_ext' : ∀ {R : Type u_3} [inst : Semiring R] {M : Type u_4} [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {f g : Polynomial R →ₗ[R] M},
  (∀ (n : ℕ), f ∘ₗ Polynomial.monomial n = g ∘ₗ Polynomial.monomial n) → f = g

@LinearEquiv.conj_apply_apply : ∀ {R₁' : Type u_1} {R₂' : Type u_2} {M₁' : Type u_3} {M₂' : Type u_4}
  [inst : CommSemiring R₁'] [inst_1 : CommSemiring R₂'] [inst_2 : AddCommMonoid M₁'] [inst_3 : AddCommMonoid M₂']
  [inst_4 : Module R₁' M₁'] [inst_5 : Module R₂' M₂'] {σ₁'₂' : R₁' →+* R₂'} {σ₂'₁' : R₂' →+* R₁'}
  [inst_6 : RingHomInvPair σ₁'₂' σ₂'₁'] [inst_7 : RingHomInvPair σ₂'₁' σ₁'₂'] (e : M₁' ≃ₛₗ[σ₁'₂'] M₂')
  (f : Module.End R₁' M₁') (x : M₂'), (e.conj f) x = e (f (e.symm x))

@Finsupp.card_Iic : ∀ {ι : Type u_2} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α]
  [inst_2 : IsBotZeroClass α] [inst_3 : OrderBot α] [inst_4 : LocallyFiniteOrder α] [inst_5 : DecidableEq ι]
  [inst_6 : DecidableEq α] (f : ι →₀ α), (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card

def BoxIntervalChecks.no_decidable_eq.{u_2} : {τ : Type u_2} → [Fintype τ] → (τ → ℕ) → Finset (τ →₀ ℕ) :=
fun {τ} [Fintype τ] r ↦
  Finset.map Finsupp.equivFunOnFinite.symm.toEmbedding (Fintype.piFinset fun j ↦ Finset.range (r j + 1))

@Finsupp.weight : {σ : Type u_2} →
  {M : Type u_3} →
    {R : Type u_4} → [inst : Semiring R] → (σ → M) → [inst_1 : AddCommMonoid M] → [Module R M] → (σ →₀ R) →+ M

@Finsupp.weight_eq_sum : ∀ {σ : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Semiring R] (w : σ → M)
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] [inst_3 : Fintype σ] (f : σ →₀ R),
  (Finsupp.weight w) f = ∑ i, f i • w i
